WITH kept_keys AS (SELECT id, status FROM subscriptions EXCEPT SELECT id, status FROM subscriptions WHERE YEAR(end_date) = 2025), kept_rows AS (SELECT s.* FROM subscriptions s JOIN kept_keys k ON s.id = k.id AND s.status = k.status) SELECT s.customer_id, s.plan, s.monthly_fee, s.status, CASE WHEN status RLIKE '^(EXPIRED|ACTIVE)$' THEN 'EXTENDED' WHEN status RLIKE '^(CANCELLED|PAUSED)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS status_zone, (SELECT AVG(x.balance) FROM accounts x WHERE x.customer_id = s.customer_id) AS avg_account_balance FROM kept_rows s ORDER BY monthly_fee DESC NULLS FIRST
